1	#!/usr/bin/env node
2	// PostToolUse-хук (Write|Edit): ASCII-пунктуация в тексте, который пишет Claude.
3	// Проверяется только записанный фрагмент (content или new_string), а не весь файл: символ, который был
4	// в файле до правки, запись не блокирует.
5	let raw = '';
6	process.stdin.on('data', (d) => (raw += d));
7	process.stdin.on('end', () => {
8	  let input;
9	  try {
10	    input = JSON.parse(raw);
11	  } catch {
12	    process.exit(0); // битый вход - не повод останавливать работу
13	  }
14	  const ti = (input && input.tool_input) || {};
15	  const text = ti.content != null ? ti.content : ti.new_string != null ? ti.new_string : '';
16	  // тире, кривые кавычки, точка-маркер, многоточие одним символом, елочки, стрелки, значки, флаги и эмодзи
17	  const bad = /[\u2010-\u2015\u2018\u2019\u201c-\u201e\u2022\u2026\u00ab\u00bb\u2190-\u21ff\u2300-\u23ff\u25a0-\u25ff\u2600-\u27bf\u2b00-\u2bff]|[\u{1f1e6}-\u{1f1ff}\u{1f300}-\u{1faff}]/u;
18	  if (typeof text !== 'string' || !bad.test(text)) process.exit(0);
19	
20	  const hits = [];
21	  text.split('\n').forEach((line, i) => {
22	    if (bad.test(line)) hits.push(i + 1);
23	  });
24	  const file = ti.file_path || 'файл';
25	  console.log(
26	    JSON.stringify({
27	      decision: 'block',
28	      reason:
29	        'ASCII-пунктуация: в записанном тексте (' +
30	        file +
31	        ') есть тире, стрелка, кривые или елочные кавычки, многоточие одним символом или значок, строки фрагмента: ' +
32	        hits.join(', ') +
33	        '. Замени на дефис, "->", прямые кавычки или "..." и запиши снова. Если символ нужен по смыслу ' +
34	        '(данные, тест, чужая цитата), оставь его.',
35	    })
36	  );
37	  process.exit(0);
38	});
